-- Index on OrderItem.productImageUploadId (SECURITY.md SEC-067).
-- Specification: docs/DATA_MODEL.md sections 6.12, 17, and 21.4.
--
-- Every "is this upload referenced by an order item" lookup (unauthenticated file serving, the
-- per-store cap on unattached uploads, the orphan cleanup) and the Restrict check of every
-- "Upload" delete scanned the whole "OrderItem" table, because no index led with this column.
--
-- Generated by Prisma from @@index([productImageUploadId]) on OrderItem; no raw SQL.
-- Plain CREATE INDEX (not CONCURRENTLY): Prisma runs a migration file as one script, and
-- CONCURRENTLY cannot run inside a transaction block. It blocks writes to "OrderItem" while the
-- index is built. No shared or production database exists yet (docs/DATA_MODEL.md section 17).

-- CreateIndex
CREATE INDEX "OrderItem_productImageUploadId_idx" ON "OrderItem"("productImageUploadId");
